package com.termux.app.workspace;
import android.app.*;import android.provider.Settings;import org.json.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentMessageTimeTest {
 @Test public void summaryOccursOnceAfterFinalAndOldHistoryHasNone()throws Exception{JSONObject summary=new JSONObject().put("request","turn").put("completedAt",1793610000000L).put("durationMs",16000);JSONObject old=new JSONObject().put("key","old").put("message","old").put("kind","text").put("body","old"),comment=new JSONObject().put("key","c").put("message","c").put("kind","text").put("body","progress"),finalRow=new JSONObject().put("key","f").put("message","f").put("kind","text").put("body","answer").put("requestSummary",summary);java.util.List<JSONObject> input=Arrays.asList(old,comment,finalRow);java.util.List<JSONObject> rows=AgentMessageTime.captions(input);assertEquals(4,rows.size());assertEquals("completionTime",rows.get(3).optString("kind"));assertEquals("request-summary:turn",rows.get(3).optString("key"));assertEquals(rows.toString(),AgentMessageTime.captions(input).toString());assertEquals(1,AgentMessageTime.captions(Collections.singletonList(old)).size());}
 @Test public void ruEnDeviceClockAndUnknownDuration()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();TimeZone old=TimeZone.getDefault();try{TimeZone.setDefault(TimeZone.getTimeZone("UTC"));JSONObject s=new JSONObject().put("completedAt",1793595780000L).put("durationMs",16000);WorkspaceLanguage.select(a,"ru");Settings.System.putString(a.getContentResolver(),Settings.System.TIME_12_24,"24");assertTrue(AgentMessageTime.caption(a,s).startsWith("Работал 16 с · "));WorkspaceLanguage.select(a,"en");Settings.System.putString(a.getContentResolver(),Settings.System.TIME_12_24,"12");assertTrue(AgentMessageTime.caption(a,s).startsWith("Worked for 16s · "));assertTrue(AgentMessageTime.shortTime(a,s.optLong("completedAt")).matches(".*(AM|PM).*"));s.remove("durationMs");assertEquals(AgentMessageTime.shortTime(a,s.optLong("completedAt")),AgentMessageTime.caption(a,s));assertTrue(AgentMessageTime.full(a,s.optLong("completedAt")).contains("UTC"));}finally{TimeZone.setDefault(old);}}
 @Test public void narrowLargeFontSummaryWrapsAndCanBeOpened()throws Exception{for(String language:new String[]{"ru","en"}){Activity a=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceLanguage.select(a,language);android.content.res.Configuration config=new android.content.res.Configuration(a.getResources().getConfiguration());config.fontScale=1.8f;a.getResources().updateConfiguration(config,a.getResources().getDisplayMetrics());a.getResources().getDisplayMetrics().scaledDensity=a.getResources().getDisplayMetrics().density*1.8f;final int[] taps={0};AgentChatView view=new AgentChatView(a,row->taps[0]++,()->{},()->{},()->{},()->{});JSONObject summary=new JSONObject().put("request","narrow").put("completedAt",1793610000000L).put("durationMs",3696000);JSONObject row=new JSONObject().put("key","final").put("message","answer").put("kind","text").put("body","Final answer").put("requestSummary",summary);view.rows(java.util.Collections.singletonList(row),false);view.scale(150);int width=view.dp(240);view.measure(android.view.View.MeasureSpec.makeMeasureSpec(width,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(view.dp(220),android.view.View.MeasureSpec.EXACTLY));view.layout(0,0,width,view.dp(220));android.widget.TextView caption=view.findViewWithTag("completion-answer");assertNotNull(caption);assertTrue(caption.getWidth()>0);assertTrue(caption.getWidth()<=width);assertTrue(caption.getLineCount()>0);assertFalse(caption.getText().toString().isEmpty());caption.performClick();assertEquals(1,taps[0]);a.finish();}}

}
